module wb_monitor #(
    // Sampling offset after the clock edge. Reading AT the edge returns
    // pre-NBA values — the defect that fabricated 176 failures in config_regs.
    parameter int SAMPLE_DELAY = 1
) (
    input  logic clk,
    input  logic rst_n,
    input  logic wb_ack_o,
    input  logic [28:0] wb_adr_i,
    input  logic [31:0] wb_dat_i,
    input  logic [3:0] wb_sel_i,
    input  logic wb_we_i
);

  // A reset is a real event a stateful predictor must see. Without it the
  // model keeps state the DUT has just cleared and diverges permanently —
  // silently, and for the rest of the run.
  always @(negedge rst_n) begin
    $display("TXN wb reset t=%0t", $time);
  end

  // Transaction detected when: wb_ack_o
  always @(posedge clk) begin
    #SAMPLE_DELAY;                 // sample after non-blocking assignments commit
    if (rst_n && (wb_ack_o)) begin
        if ((wb_we_i) == 1)
          $display("TXN wb write t=%0t addr=%0h data=%0h sel=%0h", $time, wb_adr_i, wb_dat_i, wb_sel_i);
        else if ((wb_we_i) == 0)
          $display("TXN wb read t=%0t addr=%0h", $time, wb_adr_i);
    end
  end

endmodule
